 20	
 21	/**
 22	 * The step 1 form (ADR-0004): Signal Forms over the shared validation core. The editing model is
 23	 * `Record<string, string | boolean>` (never null); each field has exactly one `validate()` that
 24	 * calls the pure `validateField`. Built once per instance, hydrated from the wizard state; a
 25	 * different configuration means a new instance (the page recreates it).
 26	 */
 27	@Component({
 28	  selector: 'app-quote-form',
 29	  imports: [FormField, FormRoot],
 30	  templateUrl: './quote-form.html',
 31	  styleUrl: './quote-form.css',
 32	})
 33	export class QuoteForm implements OnInit {
 34	  readonly configs = input.required<FieldConfig[]>();
 35	  readonly countryCode = input.required<string>();
 36	
 37	  private readonly appRef = inject(ApplicationRef);
 38	  private readonly injector = inject(Injector);
 39	  private readonly clock = inject(CLOCK);
 40	  private readonly quote = inject(QuoteStore);
 41	  private readonly router = inject(Router);
 42	
 43	  protected form!: FieldTree<RawValues>;
 44	  /** Copies the editing model into the wizard state, key by key, only what changed since the last copy. */
 45	  private flushModel: () => void = () => undefined;
 46	
 47	  ngOnInit(): void {
 48	    const configs = this.configs();
 49	    const model = signal<RawValues>(hydrate(configs, this.quote.values()));
 50	    this.form = form(
 51	      model,
 52	      (root) => {
 53	        for (const config of configs) {
 54	          validate(root[config.key], ({ value }) => {
 55	            const message = validateField(config, value(), this.clock());
 56	            return message ? { kind: 'custom', message } : undefined;
 57	          });
 58	        }
 59	      },
 60	      {
 61	        injector: this.injector,
 62	        submission: {
 63	          // Signal Forms decides validity: every field error, parse errors included, blocks.
 64	          action: async () => {
 65	            // The model-to-store effect runs on the next change detection; a keyboard Enter can
 66	            // arrive before it (Space on the consent box, then Enter). Flush it so the store
 67	            // holds exactly what the user sees.
 68	            this.flushModel();
 69	            if (this.quote.completeStep1(configs) !== null) {
 70	              await this.router.navigate(['/', this.countryCode().toLowerCase(), 'planes']);
 71	            }
 72	            return undefined;
 73	          },
 74	          onInvalid: (root) => {
 75	            const first = configs.find((config) => root[config.key]().invalid());
 76	            if (first) root[first.key]().focusBoundControl();
 77	          },
 78	        },
 79	      },
 80	    );
 81	
 82	    // The raw editing values are written to the wizard state on every change (ADR-0003). Keys of
 83	    // number and date fields are written only by `syncNative` (one writer per key, R3-F05):
 84	    // the browser may hold text the model does not, and the store must follow what the control reads.
 85	    const nativeKeys = new Set(configs.filter((c) => c.type === 'number' || c.type === 'date').map((c) => c.key));
 86	    let synced: RawValues = { ...model() };
 87	    this.flushModel = () => {
 88	      const current = model();
 89	      for (const [key, value] of Object.entries(current)) {
 90	        if (!nativeKeys.has(key) && synced[key] !== value) this.quote.setValue(key, value);
 91	      }
 92	      synced = { ...current };
 93	    };
 94	    effect(
 95	      () => {
 96	        model();
 97	        untracked(() => this.flushModel());
 98	      },
 99	      { injector: this.injector },
100	    );
101	  }
102	
103	  /** The two narrowing accessors of ADR-0004: the only casts, selected by the field type. */
104	  protected text(key: string): FieldTree<string> {
105	    return this.form[key] as unknown as FieldTree<string>;
106	  }
107	  protected flag(key: string): FieldTree<boolean> {
108	    return this.form[key] as unknown as FieldTree<boolean>;
109	  }
110	
111	  /**
112	   * Runs before the browser applies a keystroke to a number input. Signal Forms writes the model
113	   * back into the DOM from a deferred flush; if that flush is still pending when the next key
114	   * makes the text unparseable (`1` then `e`), it would overwrite the text being typed with the
115	   * stale model value. Flushing now makes it a no-op (the DOM already holds that value), so the
116	   * typed text stays visible. The model is never touched here.
117	   */
118	  protected flushBindings(): void {
119	    this.appRef.tick();
120	  }
121	
122	  /**
123	   * After every input on a number or date field, the only writer of that key in the store: text
124	   * the browser cannot parse (`validity.badInput`) is stored as '' (a partly cleared date reads
125	   * as '' too), anything else as the control reads it. The control's own model is left alone on
126	   * purpose: writing '' to it makes Signal Forms write '' into the DOM, which erases the text the
127	   * user typed (R1-F03). The text stays visible; the store, the storage and the output hold ''
128	   * (a reload never restores a stale valid value), and the field is invalid through the Signal
129	   * Forms parse error, so "Continuar" blocks.
130	   */
131	  protected syncNative(event: Event, key: string): void {
132	    const el = event.target as HTMLInputElement;
133	    this.quote.setValue(key, el.validity.badInput ? '' : el.value);
134	  }
135	
136	  /**
137	   * The message to show (spec AC-09): text the browser cannot parse is an empty value for a
138	   * required field (`requiredMessage ?? errorMessage`); for an optional field it is an error
139	   * (`errorMessage`, or the fallback).
140	   */
141	  protected errorOf(config: FieldConfig): string | null {
142	    const state = this.form[config.key]();
143	    if (!state.touched() || !state.invalid()) return null;
144	    const errors = state.errors();
145	    if (errors.some((error) => error.kind === 'parse')) {
146	      return validateField(config, '', this.clock()) ?? (config.errorMessage.trim() || FALLBACK_MESSAGE);
147	    }
148	    return errors[0]?.message ?? null;
149	  }
150	
151	  protected describedBy(config: FieldConfig, error: string | null): string | null {
152	    const ids = [
153	      config.helpText ? `${config.key}-help` : '',
154	      error ? `${config.key}-error` : '',
155	    ].filter(Boolean);
156	    return ids.length > 0 ? ids.join(' ') : null;
157	  }
158	}
