    await expect(year).toHaveValue('');
    await continuar(page).click();
    await expectDescribedBy(page, 'Modelo (año)', 'El modelo debe estar entre los últimos 20 años y el próximo año.');
    await expect(page).toHaveURL(/\/co\/datos$/);
  });
});

